<?php if($settingsUser['role']==='superadmin'):?><section class="panel settings-section"><h2>Brand icon</h2><form method="post" action="/admin/settings/icon" enctype="multipart/form-data" class="stack"><?=csrf()?><?php if($brandIcon):?><div class="brand-preview"><img src="/uploads/<?=e($brandIcon)?>" alt="Current brand icon"><span>Current icon</span></div><?php endif?><label>Upload an icon <small>JPEG, PNG, WebP, or GIF. A square image works best.</small><input type="file" name="brand_icon" accept="image/jpeg,image/png,image/webp,image/gif" <?=$brandIcon?'':'required'?>></label><div class="inline"><button>Save icon</button><?php if($brandIcon):?><button class="secondary" name="remove" value="1" formnovalidate>Use default pie</button><?php endif?></div></form></section><section class="panel settings-section"><h2>Sessions</h2><form method="post" action="/admin/settings" class="stack"><?=csrf()?><label>Session inactivity timeout <small>Minutes before inactive users must sign in again. Enter 0 for no inactivity timeout.</small><input type="number" name="session_timeout_minutes" value="<?=e($sessionMinutes)?>" min="0" max="5256000" required inputmode="numeric"></label><button>Save session settings</button></form><p class="muted">Changes apply globally. Existing sessions use the new timeout on their next request.</p></section><section class="panel settings-section"><h2>Login &amp; password security</h2><form method="post" action="/admin/settings/security" class="stack"><?=csrf()?><div class="security-grid"><label>Failed attempts allowed<small>Per username and client IP within the measurement window.</small><input type="number" name="login_max_attempts" value="<?=$loginPolicy['attempts']?>" min="1" max="100" required></label><label>Measurement window<small>Minutes in which failed attempts are counted.</small><input type="number" name="login_window_minutes" value="<?=$loginPolicy['window']?>" min="1" max="1440" required></label><label>Temporary lockout<small>Minutes before another sign-in attempt is allowed.</small><input type="number" name="login_lockout_minutes" value="<?=$loginPolicy['lockout']?>" min="1" max="1440" required></label><label>Minimum password length<small>Applies to regular users and Web Admins.</small><input type="number" name="password_min_length" value="<?=$passwordPolicy['min_length']?>" min="8" max="128" required></label><label>Minimum password strength<select name="password_min_strength"><option value="basic" <?=$passwordPolicy['strength']==='basic'?'selected':''?>>Basic — length only</option><option value="standard" <?=$passwordPolicy['strength']==='standard'?'selected':''?>>Standard — three character types</option><option value="strong" <?=$passwordPolicy['strength']==='strong'?'selected':''?>>Strong — all four character types</option></select></label></div><label class="toggle"><input type="checkbox" name="breach_check_enabled" value="1" <?=$passwordPolicy['breach_check']?'checked':''?>><span></span><div><b>Check compromised passwords</b><small>Reject passwords found in known breaches. Passwords are checked privately using a partial hash.</small></div></label><button>Save security settings</button></form><p class="muted">Password rules do not apply to the superadmin. Login rate limiting protects every account.</p></section><?php endif?>
